document.addEventListener("DOMContentLoaded",()=>{const t=document.getElementById("last-visited-container"),e=JSON.parse(localStorage.getItem("sjmaths_last_visited"));t&&e&&(t.innerHTML=`
            <div class="last-visited-section">
                <div class="lv-content">
                    <h3><i class="fas fa-history"></i> Pick up where you left off</h3>
                    <h2>${e.title}</h2>
                </div>
                <a href="${e.url}" class="lv-btn">Continue <i class="fas fa-arrow-right"></i></a>
            </div>
        `,t.style.display="block")});
